import {createWorld} from './scene.js';
import {FISH,SPOTS,RARITIES,UPGRADES,QUESTS,newSave,cleanSave,selectFish,tickFight} from './data.js';
const $=id=>document.getElementById(id),STORE='wonderlake-bear-v1';let save=newSave();try{save=cleanSave(JSON.parse(localStorage.getItem(STORE)))}catch{}
let world;try{world=createWorld($('world'))}catch(e){$('loading').innerHTML='<span class="loading-icon">W</span><h2>这片湖需要 3D 图形支持</h2><p>请开启浏览器硬件加速，或换用支持 WebGL 的浏览器。</p>';console.error(e);throw e;}
let state='idle',holding=false,power=0,chargeTime=0,waitTime=0,biteTime=0,fightTime=0,elapsed=0,lastTime=performance.now(),fish=null,perfect=false,easy=false,failures=0,pity=0,toastTimer=0,saveTimer=0,weatherTimer=0,soundOn=false,audio=null,audioMaster=null,mutedByPause=false;
const weathers=['晴朗','多云','微雨'];
function persist(){try{localStorage.setItem(STORE,JSON.stringify(save))}catch{const first=document.querySelector('.bottom-line>span');first.textContent='浏览器未允许保存 · 本次进度仍可游玩';}}
function phase(){return save.hour<5||save.hour>=19?'night':save.hour>=16?'dusk':'day'}
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3800)}
function tone(freq=440,duration=.12,type='sine',volume=.05){if(!soundOn||!audio)return;const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,audio.currentTime);g.gain.setValueAtTime(volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audioMaster);o.start();o.stop(audio.currentTime+duration);}
function initAudio(){if(audio)return;audio=new(window.AudioContext||window.webkitAudioContext)();audioMaster=audio.createGain();audioMaster.gain.value=.55;audioMaster.connect(audio.destination);const buffer=audio.createBuffer(1,audio.sampleRate*3,audio.sampleRate),data=buffer.getChannelData(0);let smooth=0;for(let i=0;i<data.length;i++){smooth=(smooth+(Math.random()*2-1)*.015)/1.015;data[i]=smooth}const noise=audio.createBufferSource();noise.buffer=buffer;noise.loop=true;const filter=audio.createBiquadFilter();filter.type='lowpass';filter.frequency.value=650;const gain=audio.createGain();gain.gain.value=.18;noise.connect(filter);filter.connect(gain);gain.connect(audioMaster);noise.start();}
function refreshStats(){$('coins').textContent=save.coins.toLocaleString();$('collection-count').textContent=`${Object.keys(save.collection).length} / 12`;$('rod-level').textContent=`${['初学者','轻竹','银杉','星光'][save.upgrades.rod]}鱼竿 · Lv.${save.upgrades.rod+1}`;let qi=QUESTS.findIndex((_,i)=>!save.quests.includes(i));if(qi<0)qi=2;const q=QUESTS[qi],v=Math.min(q.goal,q.value(save));$('task-counter').textContent=`${v} / ${q.goal}`;$('task-title').textContent=save.quests.length===3?'湖畔小心愿，全部达成':q.title;$('task-description').textContent=q.desc;$('task-progress').style.width=`${v/q.goal*100}%`;document.querySelector('.task-card small').innerHTML=save.quests.length===3?'小熊的下一站：集齐全部 12 种鱼':`完成奖励 <strong>✦ ${q.reward}</strong>`;}
function refreshTime(){const h=Math.floor(save.hour),m=Math.floor((save.hour%1)*60),p=phase();$('world-time').textContent=`第 ${save.day} 天 · ${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}`;$('weather-text').textContent=`${weathers[save.weather]} · ${p==='night'?'夜钓时光':p==='dusk'?'落日余晖':'宜垂钓'}`;$('day-icon').textContent=save.weather===2?'☂':p==='night'?'☾':save.weather===1?'☁':'☀';world.setPhase(save.hour,weathers[save.weather]);}
function setState(next){state=next;$('action-button').classList.toggle('status-flash',next==='bite');$('fight-meters').hidden=next!=='fight';$('cast-meter').hidden=next!=='idle'&&next!=='charging';$('cancel-button').hidden=!['waiting','bite','fight'].includes(next);const contents={idle:['今天，会遇见谁呢？','让好运落进湖里','按住蓄力，松开抛竿。金色区域能带来好运。','按住 · 蓄力抛竿','⌁'],charging:['瞄准那片闪闪的水面','把握抛竿的力度','在金色区域松开，来一次精准抛竿。','松开 · 抛出鱼线','⌁'],waiting:[perfect?'漂亮！精准抛竿':'鱼线轻轻落入湖中','等一位水下的朋友','留意浮漂！咬钩时，点击按钮或按空格起钩。','静静等待咬钩…','◌'],bite:['咬钩了！就是现在！','有鱼来敲门！','快点击或按空格起钩，别让它溜走。','马上 · 起钩！','!'],fight:['和它跳一支水下的舞','收一点，松一点','按住收线，松开降张力；红区持续过久会断线。','按住 · 收线','⌁'],caught:['好朋友，上岸啦','奇妙的收获！','鱼类已加入图鉴，金币已收入背包。','欣赏你的收获','✦']};const c=contents[next];if(c){$('state-kicker').textContent=c[0];$('state-title').textContent=c[1];$('state-hint').textContent=c[2];$('action-label').textContent=c[3];$('action-icon').textContent=c[4];}if(next==='idle'){$('power-fill').style.width='0%';$('power-needle').style.left='0%';holding=false;power=0;} }
function chooseSpot(index){if(!Number.isInteger(index)||index<0||index>2)throw Error('无效钓点');if(state!=='idle'){toast('先收回鱼线，再出发去新的钓点。');return false}save.spot=index;world.setSpot(index);$('spot-name').textContent=SPOTS[index].name;$('spot-description').textContent=SPOTS[index].description;$('scene-caption').textContent=SPOTS[index].caption;document.querySelectorAll('[data-spot]').forEach(b=>b.classList.toggle('selected',Number(b.dataset.spot)===index));persist();return true;}
function press(){if($('modal').open)return;if(audio?.state==='suspended'&&soundOn)audio.resume();if(state==='idle'){holding=true;chargeTime=0;setState('charging');tone(220,.08)}else if(state==='bite'){holding=true;fightTime=0;fish.tension=20;fish.progress=0;fish.danger=0;fish.releaseTime=0;setState('fight');tone(570,.2)}else if(state==='fight'){holding=true;}else if(state==='caught'){showCatch();}}
function release(){holding=false;if(state==='charging'){perfect=power>=.55&&power<=.8;easy=save.total===0||failures>=2;fish=selectFish({spot:save.spot,weather:weathers[save.weather],phase:phase(),luck:save.upgrades.luck,perfect,forceEasy:easy,collection:save.collection,pity});waitTime=3.5+Math.random()*3.5-(perfect?1:0);world.cast(power);setState('waiting');tone(perfect?620:370,.2);if(perfect)toast('精准抛竿！更快咬钩，更多奇妙的相遇。')}}
function cancelFishing(message='收回鱼线。再试一次吧。'){world.stop();setState('idle');fish=null;toast(message)}
function escapeFish(){failures++;pity++;tone(170,.3);cancelFishing(failures>=2?'鱼儿溜走了。下一条鱼会更温柔一点。':'鱼儿溜走了。张力太高时记得松手。')}
function completedQuests(){const won=[];QUESTS.forEach((q,i)=>{if(!save.quests.includes(i)&&q.value(save)>=q.goal){save.quests.push(i);save.coins+=q.reward;won.push(`${q.title} +${q.reward}`)}});return won;}
function catchFish(){holding=false;const isNew=!save.collection[fish.id],weight=+(Math.random()*(1.2+fish.rarity*.8)+.5+fish.rarity*.6).toFixed(2),value=Math.round([15,30,65,160][fish.rarity]*(.85+Math.random()*.5)+(perfect?5:0));fish={...fish,weight,value,isNew};save.total++;save.coins+=value;save.spotCatches[save.spot]++;save.best=Math.max(save.best,weight);save.collection[fish.id]={count:(save.collection[fish.id]?.count||0)+1,best:Math.max(save.collection[fish.id]?.best||0,weight)};pity=isNew?0:pity+1;failures=0;fish.quests=completedQuests();persist();refreshStats();world.catchFish(fish.id,fish.rarity);setState('caught');[520,650,780,1040].forEach((f,i)=>setTimeout(()=>tone(f,.23),i*100));setTimeout(()=>{if(state==='caught'&&!$('modal').open)showCatch()},1050);}
function openModal(eyebrow,html){holding=false;if(state==='charging'){world.stop();setState('idle')}$('modal-eyebrow').textContent=eyebrow;$('modal-content').innerHTML=html;if(!$('modal').open)$('modal').showModal();$('modal').scrollTop=0;}
function closeModal(){$('modal').close();holding=false;if(state==='caught'){fish=null;setState('idle');}}
function showCatch(){if(!fish||state!=='caught')return;openModal('一份来自湖底的礼物',`<div class="catch-view">${fish.isNew?'<span class="new-badge">新朋友 · 首次发现</span>':'<span class="tiny-label">又见面啦，老朋友</span>'}<div class="catch-visual">${fish.emoji}</div><span class="rarity rarity-${fish.rarity}">${RARITIES[fish.rarity]}</span><h2>${fish.name}</h2><p>${fish.desc}</p><div class="catch-stats"><div><small>这次的重量</small><b>${fish.weight.toFixed(2)} <span style="font-size:12px">kg</span></b></div><div><small>收获湖畔币</small><b>✦ ${fish.value}</b></div></div>${fish.quests.length?`<p style="color:#b38a37">完成小心愿：${fish.quests.join(' · ')}</p>`:''}<button class="primary-button" data-close>继续垂钓 <span>⌁</span></button><p style="font-size:10px">已自动收入图鉴 · 重复的鱼也有金币奖励</p></div>`);}
function showJournal(){openModal('FIELD NOTES / 湖畔观察笔记',`<h2 class="modal-title">奇鱼图鉴 <span style="font-size:15px;color:#9aaa8c">${Object.keys(save.collection).length} / 12</span></h2><p class="modal-subtitle">每一条鱼，都有自己的小秘密。偏爱的天气提高出现机会，任何时刻都有可能遇见。</p><div class="fish-grid">${FISH.map((f,i)=>{const c=save.collection[i];return`<article class="fish-card ${c?'discovered':'unknown'}"><span class="fish-emoji">${c?f.emoji:'❔'}</span><span class="rarity rarity-${f.rarity}">${RARITIES[f.rarity]}</span><h3>${c?f.name:'未曾见面的朋友'}</h3><p>${SPOTS[f.spot].name}<br>偏爱${f.pref} · ${f.phase==='night'?'夜晚':f.phase==='dusk'?'黄昏':'白天'}</p>${c?`<p>已遇见 ${c.count} 次 · 最大 ${c.best.toFixed(2)} kg</p>`:''}</article>`}).join('')}</div><p class="help-bottom">累计收获 ${save.total} 条 · 最重的朋友 ${save.best.toFixed(2)} kg · ${Object.keys(save.collection).length===12?'全图鉴达成！你是这片湖的奇鱼大师。':'去不同的水域走走，会有新的发现。'}</p>`);}
function showShop(){openModal('LITTLE WORKSHOP / 小熊的装备间',`<h2 class="modal-title">给下一次冒险，添点好运</h2><p class="modal-subtitle">你的钱包：✦ ${save.coins} 湖畔币。升级永久生效，鱼饵与换钓点始终免费。</p>${UPGRADES.map(u=>{const lv=save.upgrades[u.key],cost=u.cost[lv];return`<div class="shop-row"><div class="shop-icon">${u.icon}</div><div class="shop-detail"><h3>${u.name} <span style="font-size:11px;opacity:.5">Lv.${lv+1}</span></h3><p>${u.desc}</p><div class="level-dots">${[0,1,2].map(i=>`<i class="${i<lv?'active':''}"></i>`).join('')}</div></div><button class="shop-buy" data-upgrade="${u.key}" ${lv===3||save.coins<cost?'disabled':''}>${lv===3?'已升至满级':`升级 ✦ ${cost}`}</button></div>`}).join('')}`);}
function buyUpgrade(key){const item=UPGRADES.find(u=>u.key===key);if(!item)throw Error('无效装备');const lv=save.upgrades[key],cost=item.cost[lv];if(lv>=3||save.coins<cost)return false;save.coins-=cost;save.upgrades[key]++;persist();refreshStats();showShop();tone(740,.18);toast(`${item.name}升级了！`);return true;}
function showTasks(){openModal('LITTLE WISHES / 给平凡一天的小目标',`<h2 class="modal-title">湖畔小心愿</h2><p class="modal-subtitle">不着急，每一次抛竿都是进展。达成时自动领取奖励。</p>${QUESTS.map((q,i)=>{const v=Math.min(q.goal,q.value(save));return`<div class="task-row"><div><h3>${q.title}</h3><strong>${save.quests.includes(i)?'✓ 已完成':`✦ ${q.reward}`}</strong></div><p>${q.desc} · ${v} / ${q.goal}</p><div class="mini-track"><span style="width:${v/q.goal*100}%"></span></div></div>`}).join('')}`);}
function showCamp(){if(state!=='idle'){toast('先收回鱼线，再让小熊休息。');return}openModal('SLOW DAYS / 时间慢慢走',`<h2 class="modal-title">在湖边，偷一个懒</h2><p class="modal-subtitle">喝杯热茶，等一场好风景。休息不花费金币，还会迎来新的天气。</p><div class="camp-buttons"><button data-rest="8"><span>☀</span>等到清晨<small>浅滩的鱼开始散步</small></button><button data-rest="17"><span>◒</span>等到黄昏<small>草莓河豚最爱落日</small></button><button data-rest="21"><span>☾</span>等到夜晚<small>星星落进月影深潭</small></button></div>`);}
function rest(hour){if(![8,17,21].includes(hour)||state!=='idle')return false;if(hour<=save.hour)save.day++;save.hour=hour;save.weather=(save.weather+1)%3;weatherTimer=0;refreshTime();persist();closeModal();toast(`小熊伸了个懒腰。现在${weathers[save.weather]}，去看看谁在湖里吧。`);return true;}
function showHelp(){openModal('HOW TO PLAY / 和小熊一起出发',`<h2 class="modal-title">钓鱼，只需要一点耐心</h2><p class="modal-subtitle">鼠标、触屏或空格键都可以玩。聚焦钓鱼按钮后，Enter 可切换按住与松手。打开面板时，钓鱼会暂停。</p><div class="help-steps"><div class="help-step"><b><span>1</span>按住蓄力，松开抛竿</b><p>在金色区域松开，获得精准抛竿加成。没有抛准也能钓到鱼。</p></div><div class="help-step"><b><span>2</span>浮漂跳动，马上起钩</b><p>按钮闪烁时，点击或按空格。你有 3 秒钟回应。</p></div><div class="help-step"><b><span>3</span>按住收线，松手降张力</b><p>鱼挣扎时张力上涨更快。不要让张力在红区停留超过 1 秒。</p></div><div class="help-step"><b><span>4</span>发现奇鱼，升级装备</b><p>所有鱼自动换取金币，并永久记入图鉴。三个钓点各有四种奇鱼。</p></div></div><p class="help-bottom">拖动湖面旋转视角 · 滚轮缩放 · C 打开图鉴 · E 打开工坊 · Esc 关闭面板或收回鱼线<br>钓鱼失败没有损失，鱼饵无限。进度保存在当前浏览器，清理浏览器数据会清除存档。<br>世界时间会自然流动；想立即换个时段，点右侧「休息一下」。</p>`);}
$('action-button').addEventListener('pointerdown',e=>{e.preventDefault();e.currentTarget.setPointerCapture(e.pointerId);press()});$('action-button').addEventListener('pointerup',e=>{e.preventDefault();release()});$('action-button').addEventListener('pointercancel',()=>{holding=false;if(state==='charging')setState('idle')});$('cancel-button').onclick=()=>cancelFishing();document.querySelectorAll('[data-spot]').forEach(b=>b.onclick=()=>chooseSpot(+b.dataset.spot));$('journal-button').onclick=showJournal;$('shop-button').onclick=showShop;$('task-button').onclick=showTasks;$('mobile-task-button').onclick=showTasks;$('camp-button').onclick=showCamp;$('help-button').onclick=showHelp;$('modal-close').onclick=closeModal;$('camera-reset').onclick=()=>world.resetCamera();$('modal').addEventListener('cancel',e=>{e.preventDefault();closeModal()});$('modal').addEventListener('click',e=>{if(e.target===$('modal')){const r=$('modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});$('modal-content').addEventListener('click',e=>{const target=e.target.closest('button');if(!target)return;if(target.hasAttribute('data-close'))closeModal();if(target.dataset.upgrade)buyUpgrade(target.dataset.upgrade);if(target.dataset.rest)rest(+target.dataset.rest)});
$('sound-toggle').onclick=()=>{try{initAudio();soundOn=!soundOn;if(soundOn)audio.resume();audioMaster.gain.setTargetAtTime(soundOn?.55:0,audio.currentTime,.1);$('sound-toggle').textContent=soundOn?'♪':'♫';$('sound-toggle').setAttribute('aria-label',soundOn?'关闭声音':'开启声音');toast(soundOn?'听，湖边的风和水声。':'声音已关闭');if(soundOn)tone(580,.2);}catch{toast('当前浏览器暂不支持音效。')}};
$('action-button').addEventListener('keydown',e=>{if(e.code==='Enter'){e.preventDefault();if(e.repeat)return;if(holding)release();else press();}});
window.addEventListener('keydown',e=>{if(e.repeat)return;const interactive=e.target.closest('button,input,select,textarea,a');if(e.code==='Space'&&!$('modal').open){if(interactive&&e.target!==$('action-button'))return;e.preventDefault();press()}if(e.code==='Escape'&&!$('modal').open&&state!=='idle'&&state!=='caught'){e.preventDefault();cancelFishing()}if(!$('modal').open&&!interactive){if(e.code==='KeyC')showJournal();if(e.code==='KeyE')showShop();}});window.addEventListener('keyup',e=>{if(e.code==='Space'){release()}});window.addEventListener('blur',()=>{holding=false;if(state==='charging')setState('idle');persist()});document.addEventListener('visibilitychange',()=>{holding=false;if(state==='charging')setState('idle');if(document.hidden){persist();if(audio&&soundOn){audio.suspend();mutedByPause=true}}else if(mutedByPause&&audio){audio.resume();mutedByPause=false;lastTime=performance.now()}});window.addEventListener('pagehide',persist);
let timeRefresh=0;
function frame(now){const dt=Math.min((now-lastTime)/1000,.05);lastTime=now;if(!document.hidden){elapsed+=dt;const paused=$('modal').open;if(!paused){save.hour+=dt/12;if(save.hour>=24){save.hour-=24;save.day++}weatherTimer+=dt;if(weatherTimer>115){weatherTimer=0;save.weather=(save.weather+1)%3;refreshTime();toast(`湖畔天气变成了${weathers[save.weather]}。`)}if(state==='charging'){chargeTime+=dt;power=(1-Math.cos(chargeTime*2.35))/2;$('power-fill').style.width=`${power*100}%`;$('power-needle').style.left=`${power*99}%`;}if(state==='waiting'){waitTime-=dt;if(waitTime<=0){biteTime=3;setState('bite');tone(850,.15);setTimeout(()=>tone(1080,.15),150)}}else if(state==='bite'){biteTime-=dt;if(biteTime<=0){failures++;pity++;cancelFishing('它轻轻游走了。下次看到浮漂跳动时，马上起钩。')}}else if(state==='fight'){fightTime+=dt;const result=tickFight(fish,dt,holding,save.upgrades,fightTime,easy);$('progress-text').textContent=`${Math.floor(fish.progress)}%`;$('progress-fill').style.width=`${fish.progress}%`;$('tension-text').textContent=`${Math.floor(fish.tension)}%`;$('tension-fill').style.width=`${Math.min(100,fish.tension)}%`;$('tension-fill').style.background=fish.tension>80?'#d57654':'#e4b666';$('tension-warning').textContent=fish.tension>85?'快松手！':result.struggle?'鱼儿正在挣扎！':'';$('action-label').textContent=holding?'正在收线 · 留意张力':'按住 · 继续收线';if(result.caught)catchFish();else if(result.escaped)escapeFish();}timeRefresh+=dt;saveTimer+=dt;if(timeRefresh>1){timeRefresh=0;refreshTime()}if(saveTimer>10){saveTimer=0;persist()}}world.update(dt,elapsed,state,holding&&!paused);}requestAnimationFrame(frame)}
chooseSpot(save.spot);refreshStats();refreshTime();setState('idle');requestAnimationFrame(frame);setTimeout(()=>$('loading').classList.add('loaded'),350);setTimeout(()=>$('loading')?.remove(),1100);
// Read-only tools share the exact state shown in the visible game.
const ctx=document.modelContext;if(ctx?.registerTool){const lifetime=new AbortController();const tools=[{name:'read_fishing_progress',title:'查看钓鱼进度',description:'读取当前钓点、金币、图鉴、装备与钓鱼阶段，不推进游戏。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).length)throw Error('本工具不接受参数');return{spot:SPOTS[save.spot].name,state,coins:save.coins,caught:save.total,collection:Object.keys(save.collection).map(id=>FISH[id].name),upgrades:{...save.upgrades},questsCompleted:save.quests.length}}}];for(const tool of tools)try{Promise.resolve(ctx.registerTool(tool,{signal:lifetime.signal})).catch(()=>{})}catch{}window.addEventListener('pagehide',()=>lifetime.abort(),{once:true});}
